export interface MergeOptions {
  readonly maxDepth?: number;
  readonly allowPrototypeMutation?: boolean;
}

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function deepMerge<T extends Record<string, unknown>>(
  target: T,
  source: Record<string, unknown>,
  options: MergeOptions = {}
): T {
  const maxDepth = options.maxDepth ?? 10;

  function mergeRecursive(dst: Record<string, unknown>, src: Record<string, unknown>, depth: number): Record<string, unknown> {
    if (depth > maxDepth) {
      return dst;
    }
    for (const key of Object.keys(src)) {
      const srcVal = src[key];
      if (isPlainObject(srcVal)) {
        if (!isPlainObject(dst[key])) {
          dst[key] = {};
        }
        mergeRecursive(dst[key] as Record<string, unknown>, srcVal, depth + 1);
      } else {
        dst[key] = srcVal;
      }
    }
    return dst;
  }

  return mergeRecursive(target, source, 0) as T;
}

