export interface SanitizationResult {
  readonly isValid: boolean;
  readonly sanitizedPayload: Record<string, unknown>;
  readonly violations: readonly string[];
}

export function validateObjectKeys(obj: Record<string, unknown>): readonly string[] {
  const violations: string[] = [];
  const dangerousKeys = new Set(["__proto__", "constructor", "prototype"]);
  for (const key of Object.keys(obj)) {
    if (dangerousKeys.has(key)) {
      violations.push(`Dangerous key detected: ${key}`);
    }
  }
  return violations;
}

export function sanitizeInput(rawInput: unknown): SanitizationResult {
  if (typeof rawInput !== "object" || rawInput === null || Array.isArray(rawInput)) {
    return {
      isValid: false,
      sanitizedPayload: {},
      violations: ["Root payload must be an object"],
    };
  }
  const violations = validateObjectKeys(rawInput as Record<string, unknown>);
  return {
    isValid: violations.length === 0,
    sanitizedPayload: rawInput as Record<string, unknown>,
    violations,
  };
}

