import { sanitizeInput, type SanitizationResult } from "./sanitizer.js";
import { deepMerge } from "./object-merger.js";

export interface BridgeMessage {
  readonly id: string;
  readonly action: string;
  readonly params: Record<string, unknown>;
}

export class PolyglotBridge {
  public validatePayload(message: BridgeMessage): SanitizationResult {
    return sanitizeInput(message.params);
  }

  public mergeConfig(base: Record<string, unknown>, override: Record<string, unknown>): Record<string, unknown> {
    const sanitized = sanitizeInput(override);
    if (!sanitized.isValid) {
      throw new Error(`Invalid override payload: ${sanitized.violations.join(", ")}`);
    }
    return deepMerge(base, override);
  }
}

