import os
import sys
from pathlib import Path

STORAGE_ROOT = Path("/sandbox/storage").resolve()

def process_uploaded_file(relative_path: str, content: bytes) -> str:
  if "\x00" in relative_path:
    raise ValueError("Null byte detected in path")

  target_path = (STORAGE_ROOT / relative_path).resolve()
  if not str(target_path).startswith(str(STORAGE_ROOT)):
    raise PermissionError(f"Path traversal attempt detected: {relative_path}")

  target_path.parent.mkdir(parents=True, exist_ok=True)
  target_path.write_bytes(content)
  return str(target_path)

def read_stored_file(relative_path: str) -> bytes:
  target_path = (STORAGE_ROOT / relative_path).resolve()
  try:
    common = os.path.commonpath([str(STORAGE_ROOT), str(target_path)])
    if common != str(STORAGE_ROOT):
      raise PermissionError(f"Access denied: {relative_path}")
  except ValueError:
    raise PermissionError(f"Drive boundary violation: {relative_path}")

  return target_path.read_bytes()
